#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""ТІЛЬКИ ЧИТАННЯ. Перевірка зв'язку: списання коштів → витратна накладна → угода."""
import collections, os, sys, urllib.parse
BASE = "/root/unitex-finrep"
sys.path.insert(0, os.path.join(BASE, "engine"))
os.chdir(BASE)
from odata_client import ODataClient
c = ODataClient()

def get(p):
    return c._get(urllib.parse.quote(p, safe="/?&=$,'"))

def page(ent, sel=None):
    out, skip = [], 0
    while True:
        p = "/%s?$format=json&$top=1000&$skip=%d" % (ent, skip)
        if sel:
            p += "&$select=" + ",".join(sel)
        b = get(p)["value"]
        out += b
        if len(b) < 1000:
            return out
        skip += 1000

def blank(x):
    return (not x) or str(x).startswith("00000000-0000")

def d10(x):
    x = str(x or "")
    return "" if (not x or x.startswith("0001-01-01")) else x[:10]

def nm(ent):
    return {r["Ref_Key"]: (r.get("Description") or "").strip()
            for r in page(ent, ["Ref_Key", "Description"])}

acc = nm("Catalog_ВидОплаты"); art = nm("Catalog_СтатьиСчета")
ctr = nm("Catalog_Контрагенты"); cli = nm("Catalog_Клиенты")

deal = {r["Ref_Key"]: (r.get("Number") or "").lstrip("0")
        for r in page("Document_Сделка", ["Ref_Key", "Number"])}
rn = {r["Ref_Key"]: r for r in page("Document_РасходнаяНакладная",
      ["Ref_Key", "Number", "Сделка_Key", "Услуга_Key", "Сумма_УЕ", "ВидОплаты_Key",
       "Контрагент_Key", "ДатаОплаты", "СтатусСчета"])}
sch = {r["Ref_Key"]: r for r in page("Document_Счет", ["Ref_Key", "Number", "Сделка_Key"])}

rows = page("Document_СписаниеДенСредств_Счета")
t = collections.Counter(r.get("Счет_Type") or "(порожньо)" for r in rows)
print("=== Счет_Type у СписаниеДенСредств_Счета ===")
for k, n in t.most_common():
    print("   %-60s %d" % (k, n))
hit_rn = sum(1 for r in rows if r.get("Счет") in rn)
hit_sch = sum(1 for r in rows if r.get("Счет") in sch)
print("   з них ведуть на витратну накладну: %d, на доходний рахунок: %d, нікуди: %d"
      % (hit_rn, hit_sch, len(rows) - hit_rn - hit_sch))

sd = {r["Ref_Key"]: r for r in page("Document_СписаниеДенСредств")}
print("\n=== Документ СписаниеДенСредств: заповненість ключових полів (%d) ===" % len(sd))
for k in ("Через_Key", "Клиент_Key", "Контрагент_Key", "ВидОплаты_Key", "ВидОплаты2_Key",
          "Банк_Key", "ВидРасхода_Key"):
    print("   %-20s %d" % (k, sum(1 for r in sd.values() if not blank(r.get(k)))))

print("\n=== ПРИКЛАД: 3 останні списання з розшифровкою по рядках ===")
byref = collections.defaultdict(list)
for r in rows:
    byref[r["Ref_Key"]].append(r)
last = sorted(sd.values(), key=lambda r: d10(r.get("Date")))[-3:]
for h in last:
    print("\n  СПИСАННЯ №%s від %s | з рахунку «%s» | через «%s» | отримувач: %s | %s грн (%s УО) | комісія %s"
          % ((h.get("Number") or "").lstrip("0"), d10(h.get("Date")),
             acc.get(h.get("ВидОплаты_Key"), "?"), acc.get(h.get("Через_Key"), "—"),
             ctr.get(h.get("Контрагент_Key"), "") or cli.get(h.get("Клиент_Key"), "")
             or (h.get("Выдать") or "") or "—",
             h.get("Сумма"), h.get("Сумма_УЕ"), h.get("КомиссияБанка")))
    for ln in byref.get(h["Ref_Key"], []):
        tgt = rn.get(ln.get("Счет"))
        if tgt:
            print("      → витр.накл.№%-6s угода №%-5s  послуга «%s»  %s УО  постачальник %s"
                  % ((tgt.get("Number") or "").lstrip("0"),
                     deal.get(tgt.get("Сделка_Key"), "—"),
                     art.get(tgt.get("Услуга_Key"), "—"), ln.get("Сумма_УЕ"),
                     ctr.get(tgt.get("Контрагент_Key"), "—")))
        else:
            print("      → %s  %s УО  (тип %s)" % (ln.get("Счет"), ln.get("Сумма_УЕ"),
                                                   ln.get("Счет_Type")))
PYEOF
